mapper.insert:
INSERT INTO law_missing_embedding_repair_operations (
  operation_id, idempotency_key, normalized_request, request_hash, target,
  runtime_instance_id, trusted_index_revision, status, candidate_count, document_count,
  indexed_count, failed_count, lease_owner, lease_expires_at, last_error, created_at, updated_at
) VALUES (
  #{operation.operationId}, #{operation.idempotencyKey}, #{operation.normalizedRequest}, #{operation.requestHash}, #{operation.target},
  #{operation.runtimeInstanceId}, #{operation.trustedIndexRevision}, #{operation.status}, #{operation.candidateCount}, #{operation.documentCount},
  #{operation.indexedCount}, #{operation.failedCount}, #{operation.leaseOwner}, #{operation.leaseExpiresAt}, #{operation.lastError},
  #{operation.createdAt}, #{operation.updatedAt}
)

mapper.select:
SELECT 
FROM law_missing_embedding_repair_items
WHERE operation_id = #{operationId} AND ordinal = #{ordinal}

mapper.update:
    UPDATE law_missing_embedding_repair_items i
    JOIN law_missing_embedding_repair_operations o ON o.operation_id = i.operation_id
    SET i.state = 'PROCESSING', i.lease_owner = #{owner}, i.lease_expires_at = #{leaseExpiresAt},
        i.updated_at = CURRENT_TIMESTAMP(6), o.status = 'RUNNING', o.lease_owner = #{owner},
        o.lease_expires_at = #{leaseExpiresAt}, o.updated_at = CURRENT_TIMESTAMP(6)
	WHERE i.operation_id = #{operationId} AND i.ordinal = #{ordinal}
	      AND i.state = 'READY' AND o.status IN ('READY','RUNNING')
      AND (o.lease_owner IS NULL OR o.lease_expires_at <= CURRENT_TIMESTAMP(6))
	      AND o.runtime_instance_id = #{runtimeInstanceId}
      AND o.trusted_index_revision = #{trustedIndexRevision}

    UPDATE law_missing_embedding_repair_items i
    JOIN law_missing_embedding_repair_operations o ON o.operation_id = i.operation_id
    SET i.lease_owner = #{owner}, i.lease_expires_at = #{leaseExpiresAt}, i.updated_at = CURRENT_TIMESTAMP(6),
        o.status = 'RUNNING', o.lease_owner = #{owner}, o.lease_expires_at = #{leaseExpiresAt}, o.updated_at = CURRENT_TIMESTAMP(6)
	WHERE i.operation_id = #{operationId} AND i.ordinal = #{ordinal}
      AND i.state = 'PROCESSING' AND i.lease_expires_at <= CURRENT_TIMESTAMP(6)
	      AND o.status IN ('READY','RUNNING')
      AND (o.lease_owner IS NULL OR o.lease_expires_at <= CURRENT_TIMESTAMP(6))
	      AND o.runtime_instance_id = #{runtimeInstanceId}
      AND o.trusted_index_revision = #{trustedIndexRevision}

UPDATE law_missing_embedding_repair_items i
JOIN law_missing_embedding_repair_operations o ON o.operation_id = i.operation_id
SET i.lease_expires_at = #{leaseExpiresAt}, i.updated_at = CURRENT_TIMESTAMP(6),
    o.lease_expires_at = #{leaseExpiresAt}, o.updated_at = CURRENT_TIMESTAMP(6)
WHERE i.operation_id = #{operationId} AND i.ordinal = #{ordinal}
  AND i.state = 'PROCESSING' AND i.lease_owner = #{owner}
  AND o.status = 'RUNNING' AND o.lease_owner = #{owner}

    UPDATE law_missing_embedding_repair_items i
    JOIN law_missing_embedding_repair_operations o ON o.operation_id = i.operation_id
    SET i.state = 'INDEXED', i.before_index_revision = o.trusted_index_revision,
        i.after_index_revision = #{afterIndexRevision}, i.detail = #{detail},
        i.lease_owner = NULL, i.lease_expires_at = NULL, i.updated_at = CURRENT_TIMESTAMP(6),
        o.trusted_index_revision = #{afterIndexRevision}, o.indexed_count = o.indexed_count + 1,
        o.lease_owner = NULL, o.lease_expires_at = NULL, o.updated_at = CURRENT_TIMESTAMP(6)
    WHERE i.operation_id = #{operationId} AND i.ordinal = #{ordinal}
	      AND i.state = 'PROCESSING' AND i.lease_owner = #{owner}
	      AND o.status = 'RUNNING' AND o.lease_owner = #{owner}
	      AND o.runtime_instance_id = #{runtimeInstanceId}
      AND o.trusted_index_revision = #{trustedIndexRevision}

    UPDATE law_missing_embedding_repair_items i
    JOIN law_missing_embedding_repair_operations o ON o.operation_id = i.operation_id
    SET i.state = 'FAILED', i.detail = #{detail}, i.lease_owner = NULL, i.lease_expires_at = NULL,
        i.updated_at = CURRENT_TIMESTAMP(6), o.status = 'FAILED', o.failed_count = o.failed_count + 1,
        o.lease_owner = NULL, o.lease_expires_at = NULL, o.last_error = #{lastError}, o.updated_at = CURRENT_TIMESTAMP(6)
	WHERE i.operation_id = #{operationId} AND i.ordinal = #{ordinal}
	      AND i.state = 'PROCESSING' AND i.lease_owner = #{owner}
	      AND o.status IN ('READY','RUNNING') AND o.lease_owner = #{owner}
